public class TrafficLightControllerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("next(green)", "yellow", TrafficLightController.next("green"));
        check("next(yellow)", "red", TrafficLightController.next("yellow"));
        check("next(red)", "green", TrafficLightController.next("red"));
        check("next(blue)", "red", TrafficLightController.next("blue"));
        check("next(null)", "red", TrafficLightController.next(null));
        check("secondsFor(green)", 30, TrafficLightController.secondsFor("green"));
        check("secondsFor(yellow)", 5, TrafficLightController.secondsFor("yellow"));
        check("secondsFor(purple)", 0, TrafficLightController.secondsFor("purple"));
        String s = "green";
        s = TrafficLightController.next(TrafficLightController.next(TrafficLightController.next(s)));
        check("three steps from green", "green", s);
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
