public class TrafficLightController {

    public static String next(String current) {
        if (current == null) {
            return "red";
        }
        return switch (current) {
            case "green" -> "yellow";
            case "yellow" -> "red";
            case "red" -> "green";
            default -> "red";
        };
    }

    public static int secondsFor(String state) {
        if (state == null) {
            return 0;
        }
        return switch (state) {
            case "green" -> 30;
            case "yellow" -> 5;
            case "red" -> 25;
            default -> 0;
        };
    }
}
